	public NpcAdventureCombatRatingData GetCombatRatingData(long meCombatRating, long stageCombatRating)
	{
		float num = 0f;
		NpcAdventureCombatRatingData npcAdventureCombatRatingData = null;
		float num2 = 1f * (float)meCombatRating / (float)stageCombatRating;
		foreach (NpcAdventureCombatRatingData combatRatingData in CombatRatingDatas)
		{
			if (num2 >= combatRatingData.StartRate && combatRatingData.StartRate >= num)
			{
				num = combatRatingData.StartRate;
				npcAdventureCombatRatingData = combatRatingData;
			}
		}
		if (npcAdventureCombatRatingData == null)
		{
			Debug.LogError("NpcAdventureSettings GetCombatRatingData Failed! MeCombatRating:" + meCombatRating + ", StageCombatRating:" + stageCombatRating);
		}
		return npcAdventureCombatRatingData;
	}

